```javascript
// Simple application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Adds various HTTP security headers

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' }
});
app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Disable x-powered-by header to avoid fingerprinting
app.disable('x-powered-by');

// Input validation middleware helper
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array().map(e => ({ field: e.path, message: e.msg }))
    });
  }
  next();
};

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with optional query parameter validation
app.get('/users', 
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('offset').optional().isInt({ min: 0 }).toInt(),
  ],
  validate,
  (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if provided
    const limit = req.query.limit || users.length;
    const offset = req.query.offset || 0;

    res.json(users.slice(offset, offset + limit));
  }
);

// 404 handler - catch undefined routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found', path: req.path });
});

// Global error handler - MUST be last middleware
app.use((err, req, res, next) => {
  // Log error internally (use a proper logger in production)
  console.error(`Error: ${err.message}`, { 
    stack: err.stack,
    path: req.path,
    method: req.method 
  });

  // Don't leak error details to client in production
  const isDev = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDev ? err.message : 'Internal Server Error',
    ...(isDev && { stack: err.stack })
  });
});

// Use environment variable for port
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### Summary of Changes

| Improvement | Security Benefit |
|-------------|------------------|
| `helmet()` middleware | Adds CSP, X-Frame-Options, X-Content-Type-Options, etc. |
| Rate limiting | Prevents DoS/brute-force attacks |
| Body size limits | Prevents large payload attacks |
| Input validation | Prevents injection attacks, ensures data integrity |
| Global error handler | Prevents stack trace leakage |
| 404 handler | Consistent error responses |
| Disabled `x-powered-by` | Reduces server fingerprinting |
| Environment variables | Separates config from code |

### Required Dependencies

```bash
npm install helmet express-rate-limit express-validator
```

